export default {
  state: {
    allData: [], //控制菜单收缩
    ipCount: [],
    timeCount: [],
    PrCount: [],
  },
  mutations: {
    reserveData(state, data) {
      state.allData = data.reverse();
    },
    getIpCount(state, data) {
      state.ipCount = data;
    },
    getTimeCount(state, data) {
      state.timeCount = data;
    },
    getPrCount(state, data) {
      state.PrCount = data;
    },
  },
};
