<template>
  <div>
    <el-card class="box-card">
      <div class="settings">
        <el-form :inline="true" :model="setting" class="demo-form-inline">
          <el-row type="flex" class="row-bg" justify="space-around">
            <el-col :span="8"
              ><div class="grid-content bg-purple">
                <el-form-item label="IP地址" class="form-item-wrapper">
                  <el-input
                    placeholder="IP"
                    v-model="setting.ip"
                    clearable
                  ></el-input>
                </el-form-item></div
            ></el-col>
            <el-col :span="8"
              ><div class="grid-content bg-purple-light">
                <el-form-item label="抓包大小(KB)" class="form-item-wrapper">
                  <el-input
                    placeholder="Size"
                    v-model="setting.size"
                    clearable
                  ></el-input>
                </el-form-item></div
            ></el-col>
          </el-row>
        </el-form>
      </div>
      <el-row type="flex" class="row-bg" justify="space-around">
        <el-col :span="12">
          <div class="b1">
            <el-button type="primary" @click="startCapture">开始</el-button>
          </div>
        </el-col>
        <el-col :span="12">
          <div class="b1">
            <el-button type="primary" @click="stopCapture">停止</el-button>
          </div>
        </el-col>
      </el-row>
    </el-card>
    <h1>Available Files for Download</h1>
    <el-table
      ref="multipleTable"
      :data="files"
      style="width: 100%"
      height="400"
      @selection-change="handleSelectionChange"
      row-key="name"
    >
      <el-table-column type="selection" :reserve-selection="true" width="55">
      </el-table-column>
      <el-table-column prop="name" label="File Name"> </el-table-column>
    </el-table>
    <el-button
      class="bt"
      :disabled="selectedFiles.length === 0"
      @click="downloadFiles"
      type="primary"
      >Download Selected</el-button
    >
  </div>
</template>

<script>
import axios from "axios";

export default {
  data() {
    return {
      setting: {
        ip: "",
        size: "",
      },
      files: [],
      selectedFiles: [],
      count: 0,
      intervalId: null,
    };
  },
  watch: {
    tableData() {
      //默认勾选上所有的选项
      this.$nextTick(() => {
        for (const item of this.files) {
          this.$refs.multipleTable.toggleRowSelection(item, true);
        }
      });
    },
  },
  methods: {
    validateIP(ip) {
      const ipRegex =
        /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
      return ipRegex.test(ip);
    },
    validatePacketSize(size) {
      const sizeNumber = parseInt(size, 10);
      return sizeNumber > 0;
    },
    startCapture() {
      if (!this.validateIP(this.setting.ip)) {
        this.$message({
          showClose: true,
          message: "无效的IP地址",
          type: "warning",
        });
        return;
      }
      if (!this.validatePacketSize(this.setting.size)) {
        this.$message({
          showClose: true,
          message: "无效的抓包大小",
          type: "warning",
        });
        return;
      }
      axios
        .post("http://localhost:5000/start_capture", this.setting)
        .then((response) => {
          this.message = response.data.status;
          this.$message({
            showClose: true,
            message: "抓包已开始",
            type: "success",
          });
        })
        .catch((error) => {
          console.error("Error starting the capture:", error);
          this.message = "Failed to start capture";
          this.$message({
            showClose: true,
            message: "抓包失败",
            type: "error",
          });
        });
    },
    stopCapture() {
      axios
        .post("http://localhost:5000/stop_capture")
        .then((response) => {
          this.message = response.data.status;
          this.$message({
            showClose: true,
            message: "抓包已停止",
            type: "success",
          });
        })
        .catch((error) => {
          console.error("Error stopping the capture:", error);
          this.message = "Failed to stop capture";
          this.$message({
            showClose: true,
            message: "抓包停止失败",
            type: "error",
          });
        });
    },
    fetchFiles() {
      axios
        .get("http://localhost:5000/files")
        .then((response) => {
          // 如果文件名是唯一的，可以考虑使用这种方式更新数据
          this.files = response.data.map((file) => ({ name: file }));
          // 重新设置选中状态
          // this.$nextTick(() => {
          //   this.$refs.table.clearSelection();
          //   for (let i = 0; i < this.files.length; i++) {
          //     if (this.files[i].check == true) {
          //       this.$refs.table.toggleRowSelection(this.files[i], true);
          //     }
          //   }
          // });
        })
        .catch((error) => console.error("Error fetching files: ", error));
    },
    downloadFiles() {
      const filename = new Date().toISOString() + ".zip";
      axios
        .post(
          "http://localhost:5000/download",
          {
            files: this.selectedFiles,
            filename: filename,
          },
          { responseType: "blob" }
        )
        .then((response) => {
          const url = window.URL.createObjectURL(new Blob([response.data]));
          const link = document.createElement("a");
          link.href = url;
          link.setAttribute("download", filename);
          document.body.appendChild(link);
          link.click();
          link.parentNode.removeChild(link);
        })
        .catch((error) => console.error("Failed to download files: ", error));
    },
    handleSelectionChange(selection) {
      this.selectedFiles = selection.map((item) => item.name);
    },
    startPolling() {
      this.intervalId = setInterval(this.fetchFiles, 2000); // 每5秒更新一次文件列表
    },
    stopPolling() {
      if (this.intervalId) {
        clearInterval(this.intervalId);
      }
    },
  },
  created() {
    this.startPolling();
  },
  beforeDestroy() {
    this.stopPolling();
  },
};
</script>

