<script>
import * as echarts from "echarts";

export default {
  data() {
    return {
      srcIp: [],
      visitCount: [],
      chart: null,
    };
  },
  sockets: {
    ip_count(data) {
      this.$store.commit("getIpCount", data);
    },
  },
  mounted() {
    this.initChart();
  },
  methods: {
    initChart() {
      const chartDom = document.getElementById("main1");
      this.chart = echarts.init(chartDom);
      this.updateChart();
    },
    updateChart() {
      const option = {
        xAxis: {
          max: "dataMax",
        },
        yAxis: {
          type: "category",
          data: this.srcIps,
          inverse: true,
          animationDuration: 0,
          animationDurationUpdate: 0,
          max: 5, // Only the largest 3 bars will be displayed
        },
        series: [
          {
            realtimeSort: true,
            name: "热门IP TOP5",
            type: "bar",
            data: this.visitCounts,
            label: {
              show: true,
              position: "right",
              valueAnimation: true,
            },
          },
        ],
        legend: {
          show: true,
        },
        animationDuration: 0,
        animationDurationUpdate: 3000,
        animationEasing: "linear",
        animationEasingUpdate: "linear",
      };
      this.chart.setOption(option, true);
    },
  },
  computed: {
    returnData() {
      return this.$store.state.Data.ipCount;
    },
    srcIps() {
      return this.returnData.map((item) => item.srcIp);
    },
    visitCounts() {
      return this.returnData.map((item) => item.visitCount);
    },
  },
  watch: {
    immediate: true,
    returnData(newVal, oldVal) {
      if (newVal !== oldVal) {
        this.updateChart();
      }
    },
  },
};
</script>
<template>
  <div id="main1" style="width: auto; height: 250px"></div>
</template>

<style scoped lang="less"></style>
